// slide-01.js - Cover Page
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'cover',
  index: 1,
  title: 'Global CO₂ Emissions: Who Emits, How Much, and What’s Changing'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Decorative circles (abstract CO2 bubbles)
  const makeShadow = () => ({ type: "outer", blur: 8, offset: 2, color: "000000", opacity: 0.2 });
  slide.addShape(pres.shapes.OVAL, {
    x: 6.5, y: 0.2, w: 2.2, h: 2.2,
    fill: { color: theme.secondary, transparency: 60 },
    shadow: makeShadow()
  });
  slide.addShape(pres.shapes.OVAL, {
    x: 8.0, y: 2.5, w: 1.5, h: 1.5,
    fill: { color: theme.accent, transparency: 50 },
    shadow: makeShadow()
  });
  slide.addShape(pres.shapes.OVAL, {
    x: 7.0, y: 3.8, w: 2.8, h: 2.8,
    fill: { color: theme.light, transparency: 65 },
    shadow: makeShadow()
  });
  slide.addShape(pres.shapes.OVAL, {
    x: 5.5, y: 4.0, w: 1.2, h: 1.2,
    fill: { color: theme.bg, transparency: 55 }
  });

  // Main title
  slide.addText(slideConfig.title, {
    x: 0.6, y: 1.0, w: 5.8, h: 1.8,
    fontSize: 36, fontFace: "Georgia",
    color: "FFFFFF", bold: true, align: "left",
    valign: "top", margin: 0
  });

  // Subtitle - scope
  slide.addText("Fossil Fuels & Industry, 1750–2024", {
    x: 0.6, y: 2.9, w: 5.5, h: 0.5,
    fontSize: 20, fontFace: "Calibri",
    color: theme.accent, bold: false, align: "left",
    margin: 0
  });

  // Divider line
  slide.addShape(pres.shapes.LINE, {
    x: 0.6, y: 3.55, w: 2.0, h: 0,
    line: { color: theme.accent, width: 2 }
  });

  // Data source
  slide.addText("Data: Global Carbon Budget 2025 via Our World in Data", {
    x: 0.6, y: 3.75, w: 5.5, h: 0.4,
    fontSize: 13, fontFace: "Calibri",
    color: "FFFFFF", bold: false, align: "left",
    transparency: 30, margin: 0
  });

  // Audience context
  slide.addText("For policy analysts, climate negotiators, and sustainability researchers", {
    x: 0.6, y: 4.2, w: 5.5, h: 0.4,
    fontSize: 12, fontFace: "Calibri",
    color: "FFFFFF", bold: false, align: "left",
    transparency: 40, margin: 0
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "264653", secondary: "2a9d8f", accent: "e9c46a", light: "f4a261", bg: "e76f51" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-01-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

