// slide-02.js - Global CO2 Emissions Growth (Line Chart)
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 2,
  title: 'Global CO₂ Emissions Grew from 6 Bt in 1950 to Over 35 Bt Today'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: "FFFFFF" };

  // Title
  slide.addText(slideConfig.title, {
    x: 0.4, y: 0.25, w: 9.2, h: 0.65,
    fontSize: 22, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left",
    margin: 0, fit: "shrink"
  });

  // Line chart - global CO2 emissions trajectory
  const chartData = [{
    name: "Global CO₂ (Bt)",
    labels: ["1750", "1800", "1850", "1900", "1920", "1940", "1950", "1960", "1970", "1980", "1990", "2000", "2010", "2020", "2024"],
    values: [0.003, 0.01, 0.05, 0.2, 0.9, 1.7, 6, 9.4, 14.9, 19.5, 22.7, 25.2, 33.4, 34.8, 37.4]
  }];

  slide.addChart(pres.charts.LINE, chartData, {
    x: 0.4, y: 1.0, w: 6.8, h: 3.8,
    showTitle: false,
    lineSize: 3,
    lineSmooth: true,
    chartColors: [theme.secondary],
    chartArea: { fill: { color: "FFFFFF" } },
    catAxisLabelColor: theme.primary,
    catAxisLabelFontSize: 10,
    catAxisLabelFontFace: "Calibri",
    valAxisLabelColor: theme.primary,
    valAxisLabelFontSize: 10,
    valAxisLabelFontFace: "Calibri",
    valGridLine: { color: "E8E8E8", size: 0.5 },
    catGridLine: { style: "none" },
    showLegend: false,
    valAxisMinVal: 0,
    valAxisMaxVal: 40,
    lineDataSymbol: "circle",
    lineDataSymbolSize: 5
  });

  // Inflection point annotations - right side callouts
  const calloutData = [
    { label: "Pre-1950", desc: "Slow growth, negligible emissions before industrialization", y: 1.15 },
    { label: "1950: ~6 Bt", desc: "Post-war acceleration begins", y: 2.1 },
    { label: "1990: ~20 Bt", desc: "Nearly 4x increase in 40 years", y: 3.05 },
    { label: "2024: >35 Bt", desc: "Growth slowing but no peak yet", y: 4.0 }
  ];

  calloutData.forEach((item, i) => {
    const makeShadow = () => ({ type: "outer", blur: 4, offset: 1, color: "000000", opacity: 0.08 });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 7.5, y: item.y, w: 2.3, h: 0.75,
      fill: { color: "F5F5F5" },
      rectRadius: 0.05,
      shadow: makeShadow()
    });
    slide.addText(item.label, {
      x: 7.6, y: item.y + 0.05, w: 2.1, h: 0.3,
      fontSize: 12, fontFace: "Georgia",
      color: theme.primary, bold: true, align: "left", margin: 0
    });
    slide.addText(item.desc, {
      x: 7.6, y: item.y + 0.35, w: 2.1, h: 0.35,
      fontSize: 10, fontFace: "Calibri",
      color: "666666", bold: false, align: "left", margin: 0
    });
  });

  // Source
  slide.addText("Source: Global Carbon Budget 2025 via Our World in Data", {
    x: 0.4, y: 5.1, w: 6, h: 0.3,
    fontSize: 9, fontFace: "Calibri",
    color: "999999", bold: false, align: "left", margin: 0
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("2", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "264653", secondary: "2a9d8f", accent: "e9c46a", light: "f4a261", bg: "e76f51" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-02-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

