// slide-06.js - Per Capita Trends Over Time (Horizontal Bar + Comparison)
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 6,
  title: 'Per Capita Emissions Vary Widely: ~14 t in the US vs. ~9 t in China and ~2 t in India'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: "FFFFFF" };

  // Title
  slide.addText(slideConfig.title, {
    x: 0.4, y: 0.25, w: 9.2, h: 0.65,
    fontSize: 19, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left",
    margin: 0, fit: "shrink"
  });

  // Horizontal bar chart - per capita emissions with color differentiation
  // Using chartColors array to highlight key comparisons
  const chartData = [{
    name: "Per Capita CO₂ (t)",
    labels: ["US", "Canada", "China", "S. Africa", "EU-27", "World Avg", "UK", "India", "Kenya"],
    values: [14, 14, 9, 7, 6, 4.5, 4, 2, 0.4]
  }];

  slide.addChart(pres.charts.BAR, chartData, {
    x: 0.4, y: 1.0, w: 6.3, h: 4.0,
    barDir: "bar",
    showTitle: false,
    chartColors: [theme.light],
    chartArea: { fill: { color: "FFFFFF" } },
    catAxisLabelColor: theme.primary,
    catAxisLabelFontSize: 10,
    catAxisLabelFontFace: "Calibri",
    valAxisLabelColor: theme.primary,
    valAxisLabelFontSize: 10,
    valAxisLabelFontFace: "Calibri",
    valGridLine: { color: "E8E8E8", size: 0.5 },
    catGridLine: { style: "none" },
    showLegend: false,
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: theme.primary,
    dataLabelFontSize: 10,
    dataLabelFontFace: "Calibri",
    valAxisMinVal: 0,
    valAxisMaxVal: 16
  });

  // Right side insight cards
  const makeShadow = () => ({ type: "outer", blur: 4, offset: 1, color: "000000", opacity: 0.08 });

  // US vs China card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.0, y: 1.1, w: 2.7, h: 1.2,
    fill: { color: theme.primary },
    rectRadius: 0.05,
    shadow: makeShadow()
  });
  slide.addText("US vs China", {
    x: 7.1, y: 1.15, w: 2.5, h: 0.3,
    fontSize: 12, fontFace: "Georgia",
    color: theme.accent, bold: true, align: "left", margin: 0
  });
  slide.addText("China is the largest total emitter, but per capita emissions remain far below the US: ~9 t vs ~14 t", {
    x: 7.1, y: 1.5, w: 2.5, h: 0.7,
    fontSize: 11, fontFace: "Calibri",
    color: "FFFFFF", bold: false, align: "left", valign: "top", margin: 0
  });

  // India card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.0, y: 2.55, w: 2.7, h: 1.0,
    fill: { color: theme.secondary },
    rectRadius: 0.05,
    shadow: makeShadow()
  });
  slide.addText("India's Low Baseline", {
    x: 7.1, y: 2.6, w: 2.5, h: 0.3,
    fontSize: 12, fontFace: "Georgia",
    color: "FFFFFF", bold: true, align: "left", margin: 0
  });
  slide.addText("At ~2 t per capita, India's emissions remain very low — well below the world average of ~4.5 t", {
    x: 7.1, y: 2.95, w: 2.5, h: 0.55,
    fontSize: 10, fontFace: "Calibri",
    color: "FFFFFF", bold: false, align: "left", valign: "top", margin: 0
  });

  // World average reference card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.0, y: 3.8, w: 2.7, h: 1.2,
    fill: { color: "F5F5F5" },
    rectRadius: 0.05,
    shadow: makeShadow()
  });
  slide.addText("World Average: ~4.5 t", {
    x: 7.1, y: 3.85, w: 2.5, h: 0.35,
    fontSize: 13, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left", margin: 0
  });
  slide.addText("Most wealthy nations exceed the global average by 2-3x. Only a few developing nations approach or fall below it.", {
    x: 7.1, y: 4.25, w: 2.5, h: 0.65,
    fontSize: 10, fontFace: "Calibri",
    color: "666666", bold: false, align: "left", valign: "top", margin: 0
  });

  // Source
  slide.addText("Source: Global Carbon Budget 2025 via Our World in Data", {
    x: 0.4, y: 5.1, w: 6, h: 0.3,
    fontSize: 9, fontFace: "Calibri",
    color: "999999", bold: false, align: "left", margin: 0
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("6", {
