// slide-07.js - 2024 Annual Change (Diverging Bar Chart)
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 7,
  title: '2024 Snapshot: Many Western Nations Cut Emissions While Parts of Asia and Africa Grew'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: "FFFFFF" };

  // Title
  slide.addText(slideConfig.title, {
    x: 0.4, y: 0.25, w: 9.2, h: 0.65,
    fontSize: 19, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left",
    margin: 0, fit: "shrink"
  });

  // Diverging bar chart - 2024 annual change
  // Declines (negative) and increases (positive) as % change
  const chartData = [{
    name: "2024 Annual Change (%)",
    labels: [
      "Turkmenistan/Uzbekistan",
      "Russia",
      "Vietnam",
      "Indonesia",
      "Nigeria",
      "India",
      "China",
      "EU-27",
      "UK",
      "US"
    ],
    values: [10, 2, 3, 2, 2, 3, 1, -4, -3, -1]
  }];

  slide.addChart(pres.charts.BAR, chartData, {
    x: 0.4, y: 1.0, w: 6.3, h: 4.0,
    barDir: "bar",
    showTitle: false,
    chartColors: [theme.secondary],
    chartArea: { fill: { color: "FFFFFF" } },
    catAxisLabelColor: theme.primary,
    catAxisLabelFontSize: 10,
    catAxisLabelFontFace: "Calibri",
    valAxisLabelColor: theme.primary,
    valAxisLabelFontSize: 10,
    valAxisLabelFontFace: "Calibri",
    valGridLine: { color: "E8E8E8", size: 0.5 },
    catGridLine: { style: "none" },
    showLegend: false,
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: theme.primary,
    dataLabelFontSize: 10,
    dataLabelFontFace: "Calibri"
  });

  // Right side - explanation cards
  const makeShadow = () => ({ type: "outer", blur: 4, offset: 1, color: "000000", opacity: 0.08 });

  // Declines card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.0, y: 1.1, w: 2.7, h: 1.2,
    fill: { color: theme.secondary },
    rectRadius: 0.05,
    shadow: makeShadow()
  });
  slide.addText("Declines in 2024", {
    x: 7.1, y: 1.15, w: 2.5, h: 0.3,
    fontSize: 12, fontFace: "Georgia",
    color: "FFFFFF", bold: true, align: "left", margin: 0
  });
  slide.addText("US, EU, and UK saw emissions decline, continuing a trend of gradual reductions in developed economies.", {
    x: 7.1, y: 1.5, w: 2.5, h: 0.7,
    fontSize: 10, fontFace: "Calibri",
    color: "FFFFFF", bold: false, align: "left", valign: "top", margin: 0
  });

  // Increases card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.0, y: 2.55, w: 2.7, h: 1.2,
    fill: { color: theme.bg },
    rectRadius: 0.05,
    shadow: makeShadow()
  });
  slide.addText("Increases in 2024", {
    x: 7.1, y: 2.6, w: 2.5, h: 0.3,
    fontSize: 12, fontFace: "Georgia",
    color: "FFFFFF", bold: true, align: "left", margin: 0
  });
  slide.addText("Russia, parts of SE Asia, and several African nations saw increases. Central Asia exceeded +10%.", {
    x: 7.1, y: 2.95, w: 2.5, h: 0.7,
    fontSize: 10, fontFace: "Calibri",
    color: "FFFFFF", bold: false, align: "left", valign: "top", margin: 0
  });

  // Net picture card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.0, y: 4.0, w: 2.7, h: 0.9,
    fill: { color: "F5F5F5" },
    rectRadius: 0.05
  });
  slide.addText("Mixed Global Signal", {
    x: 7.1, y: 4.05, w: 2.5, h: 0.3,
    fontSize: 12, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left", margin: 0
  });
