// slide-08.js - Energy Mix Matters (Mixed Media - Text + Chart)
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 8,
  title: 'Energy Mix Explains Why France and the UK Emit Far Less Per Capita Than Germany or the US'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: "FFFFFF" };

  // Title
  slide.addText(slideConfig.title, {
    x: 0.4, y: 0.25, w: 9.2, h: 0.65,
    fontSize: 19, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left",
    margin: 0, fit: "shrink"
  });

  // Left side - comparative bar chart of per capita emissions
  const chartData = [{
    name: "Per Capita CO₂ (t)",
    labels: ["US", "EU-27", "UK"],
    values: [14, 6, 4]
  }];

  slide.addChart(pres.charts.BAR, chartData, {
    x: 0.4, y: 1.0, w: 4.5, h: 2.5,
    barDir: "bar",
    showTitle: false,
    chartColors: [theme.light],
    chartArea: { fill: { color: "FFFFFF" } },
    catAxisLabelColor: theme.primary,
    catAxisLabelFontSize: 12,
    catAxisLabelFontFace: "Calibri",
    valAxisLabelColor: theme.primary,
    valAxisLabelFontSize: 10,
    valAxisLabelFontFace: "Calibri",
    valGridLine: { color: "E8E8E8", size: 0.5 },
    catGridLine: { style: "none" },
    showLegend: false,
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: theme.primary,
    dataLabelFontSize: 12,
    dataLabelFontFace: "Calibri",
    valAxisMinVal: 0,
    valAxisMaxVal: 16
  });

  // Key insight box below chart
  const makeShadow = () => ({ type: "outer", blur: 4, offset: 1, color: "000000", opacity: 0.08 });

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 3.7, w: 4.5, h: 1.1,
    fill: { color: theme.primary },
    rectRadius: 0.05,
    shadow: makeShadow()
  });
  slide.addText("Same Prosperity, Different Emissions", {
    x: 0.5, y: 3.75, w: 4.3, h: 0.35,
    fontSize: 13, fontFace: "Georgia",
    color: theme.accent, bold: true, align: "left", margin: 0
  });
  slide.addText("Wealthy nations with similar GDP per capita can have very different per capita emissions depending on energy choices.", {
    x: 0.5, y: 4.15, w: 4.3, h: 0.55,
    fontSize: 11, fontFace: "Calibri",
    color: "FFFFFF", bold: false, align: "left", valign: "top", margin: 0
  });

  // Right side - explanation cards
  // Low emitters card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.3, y: 1.0, w: 4.3, h: 1.4,
    fill: { color: theme.secondary },
    rectRadius: 0.05,
    shadow: makeShadow()
  });
  slide.addText("Low Per Capita: Nuclear & Renewables", {
    x: 5.4, y: 1.05, w: 4.1, h: 0.35,
    fontSize: 13, fontFace: "Georgia",
    color: "FFFFFF", bold: true, align: "left", margin: 0
  });
  slide.addText("France (~6 t EU avg), the UK (~4 t), and Portugal have much lower per capita emissions because a higher share of their electricity comes from nuclear and renewable sources rather than fossil fuels.", {
    x: 5.4, y: 1.45, w: 4.1, h: 0.85,
    fontSize: 11, fontFace: "Calibri",
    color: "FFFFFF", bold: false, align: "left", valign: "top", margin: 0
  });

  // High emitters card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.3, y: 2.6, w: 4.3, h: 1.2,
    fill: { color: theme.bg },
    rectRadius: 0.05,
    shadow: makeShadow()
  });
  slide.addText("High Per Capita: Fossil Fuel Dependent", {
    x: 5.4, y: 2.65, w: 4.1, h: 0.35,
    fontSize: 13, fontFace: "Georgia",
    color: "FFFFFF", bold: true, align: "left", margin: 0
  });
  slide.addText("Germany, the Netherlands, and the US (~14 t) rely more heavily on fossil fuels for electricity generation, driving up per capita emissions.", {
    x: 5.4, y: 3.05, w: 4.1, h: 0.65,
    fontSize: 11, fontFace: "Calibri",
    color: "FFFFFF", bold: false, align: "left", valign: "top", margin: 0
  });

  // Bottom insight
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.3, y: 4.0, w: 4.3, h: 0.8,
    fill: { color: "F5F5F5" },
