const pptxgen = require('pptxgenjs');
const pres = new pptxgen();
pres.layout = 'LAYOUT_16x9';
pres.title = 'Global CO₂ Emissions: Who Emits, How Much, and What\'s Changing';
pres.author = 'Global Carbon Budget 2025';

const theme = {
  primary: "264653",
  secondary: "2a9d8f",
  accent: "e9c46a",
  light: "f4a261",
  bg: "e76f51"
};

for (let i = 1; i <= 9; i++) {
  const num = String(i).padStart(2, '0');
  const slideModule = require(`./slide-${num}.js`);
  slideModule.createSlide(pres, theme);
}

pres.writeFile({ fileName: './output/final_deck.pptx' })
  .then(() => console.log('Presentation saved to ./output/final_deck.pptx'))
  .catch(err => console.error('Error:', err));

