// slide-05.js - Per Capita Inequality (Wide Chart + Bottom Callouts)
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 5,
  title: 'Per Capita Emissions Range from 0.1 t in Chad to ~14 t in the US and Canada'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: "FFFFFF" };

  // Title
  slide.addText(slideConfig.title, {
    x: 0.4, y: 0.25, w: 9.2, h: 0.65,
    fontSize: 19, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left",
    margin: 0, fit: "shrink"
  });

  // Wide horizontal bar chart - per capita emissions (full width)
  const chartData = [{
    name: "Per Capita CO₂ (tonnes)",
    labels: ["US", "Canada", "China", "S. Africa", "EU-27", "World Avg", "UK", "India", "Kenya", "Chad/Niger"],
    values: [14, 14, 9, 7, 6, 4.5, 4, 2, 0.4, 0.1]
  }];

  slide.addChart(pres.charts.BAR, chartData, {
    x: 0.4, y: 1.0, w: 9.2, h: 2.8,
    barDir: "bar",
    showTitle: false,
    chartColors: [theme.secondary],
    chartArea: { fill: { color: "FFFFFF" } },
    catAxisLabelColor: theme.primary,
    catAxisLabelFontSize: 10,
    catAxisLabelFontFace: "Calibri",
    valAxisLabelColor: theme.primary,
    valAxisLabelFontSize: 10,
    valAxisLabelFontFace: "Calibri",
    valGridLine: { color: "E8E8E8", size: 0.5 },
    catGridLine: { style: "none" },
    showLegend: false,
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: theme.primary,
    dataLabelFontSize: 10,
    dataLabelFontFace: "Calibri",
    valAxisMinVal: 0,
    valAxisMaxVal: 16
  });

  // Bottom row - 3 insight cards spanning full width
  const makeShadow = () => ({ type: "outer", blur: 4, offset: 1, color: "000000", opacity: 0.08 });

  // 150x gap card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 4.05, w: 2.9, h: 0.95,
    fill: { color: theme.bg },
    rectRadius: 0.05,
    shadow: makeShadow()
  });
  slide.addText("150x", {
    x: 0.5, y: 4.08, w: 2.7, h: 0.45,
    fontSize: 28, fontFace: "Georgia",
    color: "FFFFFF", bold: true, align: "center", valign: "middle", margin: 0
  });
  slide.addText("Gap: Chad/Niger (~0.1 t) vs US/Canada (~14 t)", {
    x: 0.5, y: 4.55, w: 2.7, h: 0.4,
    fontSize: 9, fontFace: "Calibri",
    color: "FFFFFF", bold: false, align: "center", valign: "top", margin: 0
  });

  // Time comparison card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 3.5, y: 4.05, w: 3.0, h: 0.95,
    fill: { color: theme.secondary },
    rectRadius: 0.05,
    shadow: makeShadow()
  });
  slide.addText("Under 2 Days = 1 Year", {
    x: 3.6, y: 4.1, w: 2.8, h: 0.35,
    fontSize: 13, fontFace: "Georgia",
    color: "FFFFFF", bold: true, align: "left", margin: 0
  });
  slide.addText("An American emits in under 2 days what a person in Mali or Niger emits in an entire year", {
    x: 3.6, y: 4.5, w: 2.8, h: 0.45,
    fontSize: 10, fontFace: "Calibri",
    color: "FFFFFF", bold: false, align: "left", valign: "top", margin: 0
  });

  // Living standards card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.7, y: 4.05, w: 3.0, h: 0.95,
    fill: { color: "F5F5F5" },
    rectRadius: 0.05
  });
  slide.addText("Similar Prosperity, Different Emissions", {
    x: 6.8, y: 4.1, w: 2.8, h: 0.35,
    fontSize: 12, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left", margin: 0
  });
  slide.addText("France & the UK emit far less per capita than the US despite similar living standards", {
    x: 6.8, y: 4.5, w: 2.8, h: 0.45,
    fontSize: 10, fontFace: "Calibri",
    color: "666666", bold: false, align: "left", valign: "top", margin: 0
  });

  // Source
  slide.addText("Source: Global Carbon Budget 2025 via Our World in Data", {
    x: 0.4, y: 5.1, w: 6, h: 0.3,
    fontSize: 9, fontFace: "Calibri",
    color: "999999", bold: false, align: "left", margin: 0
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("5", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "264653", secondary: "2a9d8f", accent: "e9c46a", light: "f4a261", bg: "e76f51" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-05-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

