// slide-07.js - 2024 Annual Change (Full-Width Chart + Top/Bottom Split Insights)
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 7,
  title: '2024 Snapshot: Many Western Nations Cut Emissions While Parts of Asia and Africa Grew'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: "FFFFFF" };

  // Title
  slide.addText(slideConfig.title, {
    x: 0.4, y: 0.25, w: 9.2, h: 0.55,
    fontSize: 19, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left",
    margin: 0, fit: "shrink"
  });

  // Top row - two colored insight banners side by side
  const makeShadow = () => ({ type: "outer", blur: 4, offset: 1, color: "000000", opacity: 0.08 });

  // Declines banner (teal)
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 0.9, w: 4.5, h: 0.65,
    fill: { color: theme.secondary },
    rectRadius: 0.05,
    shadow: makeShadow()
  });
  slide.addText("Declines: US, EU-27, UK — continuing a trend of gradual reductions", {
    x: 0.5, y: 0.9, w: 4.3, h: 0.65,
    fontSize: 11, fontFace: "Calibri",
    color: "FFFFFF", bold: false, align: "left", valign: "middle", margin: 0
  });

  // Increases banner (coral)
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.1, y: 0.9, w: 4.5, h: 0.65,
    fill: { color: theme.bg },
    rectRadius: 0.05,
    shadow: makeShadow()
  });
  slide.addText("Increases: Russia, SE Asia, Africa — Central Asia exceeded +10%", {
    x: 5.2, y: 0.9, w: 4.3, h: 0.65,
    fontSize: 11, fontFace: "Calibri",
    color: "FFFFFF", bold: false, align: "left", valign: "middle", margin: 0
  });

  // Full-width diverging bar chart
  const chartData = [{
    name: "2024 Annual Change (%)",
    labels: [
      "Turkmenistan/Uzbekistan",
      "Vietnam",
      "India",
      "Indonesia",
      "Nigeria",
      "Russia",
      "China",
      "US",
      "UK",
      "EU-27"
    ],
    values: [10, 3, 3, 2, 2, 2, 1, -1, -3, -4]
  }];

  slide.addChart(pres.charts.BAR, chartData, {
    x: 0.4, y: 1.7, w: 9.2, h: 3.1,
    barDir: "bar",
    showTitle: false,
    chartColors: [theme.secondary],
    chartArea: { fill: { color: "FFFFFF" } },
    catAxisLabelColor: theme.primary,
    catAxisLabelFontSize: 10,
    catAxisLabelFontFace: "Calibri",
    valAxisLabelColor: theme.primary,
    valAxisLabelFontSize: 10,
    valAxisLabelFontFace: "Calibri",
    valGridLine: { color: "E8E8E8", size: 0.5 },
    catGridLine: { style: "none" },
    showLegend: false,
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: theme.primary,
    dataLabelFontSize: 10,
    dataLabelFontFace: "Calibri"
  });

  // Bottom insight strip
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 4.95, w: 9.2, h: 0.45,
    fill: { color: "F5F5F5" },
    rectRadius: 0.03
  });
  slide.addText("Mixed Signal: Increases in Asia, the Middle East, and Africa offset some of the Western declines — global emissions still rising.", {
    x: 0.5, y: 4.95, w: 9.0, h: 0.45,
    fontSize: 10, fontFace: "Calibri",
    color: theme.primary, bold: false, align: "left", valign: "middle", margin: 0
  });

  // Source
  slide.addText("Source: Global Carbon Budget 2025 via Our World in Data", {
    x: 0.4, y: 5.15, w: 6, h: 0.3,
    fontSize: 9, fontFace: "Calibri",
    color: "999999", bold: false, align: "left", margin: 0
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("7", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "264653", secondary: "2a9d8f", accent: "e9c46a", light: "f4a261", bg: "e76f51" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-07-preview.pptx" });
}

module.exports = { createSlide, slideConfig };
